---@field last_error string

---@class RfApi
---@type RfApi
rf = {}

---Return the device uptime.
---@return integer Milliseconds since boot.
function rf.millis() end

---Return the strongest channel in the latest scan.
---@return RfChannel Current peak channel.
function rf.peak_channel() end

---Read the latest activity for one channel.
---@param channel RfChannel
---@return integer Relative activity from 0 to 100.
function rf.level(channel) end

---Append a timestamped message to the Lua log on the SD card.
---@param message string
function rf.log(message) end

---Return a snapshot of all channel activity values.
---@return integer[] 126 values; index 1 represents RF channel 0.
function rf.spectrum() end

---Return current analyzer and recorder status.
---@return RfStatus
function rf.status() end

---Move the analyzer cursor.
---@param channel RfChannel
function rf.set_cursor(channel) end

---Freeze or resume analyzer acquisition.
---@param frozen boolean
function rf.freeze(frozen) end

---Select the analyzer scan band.
---@param band RfBand
function rf.set_band(band) end

---Select the analyzer trace mode.
---@param trace RfTrace
function rf.set_trace(trace) end

---Capture the current levels as the DELTA baseline.
function rf.capture_baseline() end

---Clear the maximum trace history.
function rf.clear_max() end

---Toggle a watched-channel marker.
---@param channel RfChannel
function rf.toggle_watch(channel) end

---Start a new recording session or stop recording.
---@param start boolean
---@return boolean True when the requested operation succeeded.
function rf.recording(start) end

---Start or stop passive occupancy analysis.
---@param start boolean
---@return boolean True when the requested operation succeeded.
function rf.environment(start) end

---Return current CC1101, analyzer, raw recorder, and TX-policy status.
---@return SubGhzStatus
function rf.subghz_status() end

---Set a supported CC1101 frequency in MHz.
---@param frequency_mhz number
---@return boolean True when the frequency was accepted.
function rf.subghz_set_frequency(frequency_mhz) end

---Select and persist a CC1101 modulation preset.
---@param preset SubGhzPreset
function rf.subghz_set_preset(preset) end

---Select and persist the Sub-GHz TX allowlist; this does not itself transmit.
---@param region SubGhzRegion
function rf.subghz_set_region(region) end

---Start or stop the CC1101 frequency analyzer.
---@param start boolean
function rf.subghz_analyzer(start) end

---Start or stop raw GDO0 recording, optionally tuning first.
---@param start boolean
---@param frequency_mhz? number Default: `current frequency`.
---@return boolean True when the requested operation succeeded.
function rf.subghz_record(start, frequency_mhz) end

---List available .rfr and Flipper RAW .sub files.
---@return string[] Up to 32 safe library filenames.
function rf.subghz_files() end

---Replay one library file with the native progress/result UI; unavailable in analyzer builds.
---@param filename string
---@return boolean True when replay completed successfully.
function rf.subghz_replay(filename) end

---Choose the TFT screen shown after the script exits.
---@param screen RfScreen
function rf.open_screen(screen) end

---Open and clear the protected 152 x 86 Lua canvas.
---@param title? string Default: `"LUA GUI"`.
function rf.gui_begin(title) end

---Set the three firmware footer labels.
---@param left? string Default: `""`.
---@param middle? string Default: `""`.
---@param right? string Default: `""`.
function rf.gui_footer(left, middle, right) end

---Clear the Lua canvas without overwriting its firmware frame.
function rf.gui_clear() end

---Close the Lua GUI and return to the script list.
function rf.gui_close() end

---Draw clipped single-line text.
---@param x integer
---@param y integer
---@param text string
---@param color? RfColor Default: `"white"`.
function rf.gui_text(x, y, text, color) end

---Draw one clipped pixel.
---@param x integer
---@param y integer
---@param color? RfColor Default: `"white"`.
function rf.gui_pixel(x, y, color) end

---Draw a clipped line.
---@param x0 integer
---@param y0 integer
---@param x1 integer
---@param y1 integer
---@param color? RfColor Default: `"white"`.
function rf.gui_line(x0, y0, x1, y1, color) end

---Draw an outline or filled rectangle.
---@param x integer
---@param y integer
---@param width integer
---@param height integer
---@param color? RfColor Default: `"white"`.
---@param filled? boolean Default: `false`.
function rf.gui_rect(x, y, width, height, color, filled) end

---Draw an outline or filled circle.
---@param x integer
---@param y integer
---@param radius integer
---@param color? RfColor Default: `"white"`.
---@param filled? boolean Default: `false`.
function rf.gui_circle(x, y, radius, color, filled) end

---Read a hardware button during a script.
---@param button RfButton
---@return boolean True while the active-low button is pressed.
function rf.button(button) end

---Wait 0 to 1000 ms while feeding the watchdog.
---@param milliseconds integer
function rf.delay(milliseconds) end

---Start an authorized-lab RF target; unavailable in analyzer builds.
---@param target string
---@return boolean True when transmission started.
function rf.lab_start(target) end

---Stop all controlled-lab RF activity.
function rf.lab_stop() end
